        JsonNode second = json(placeOrder(1, "k-same", null, p, 2).andExpect(status().isCreated()));

        assertThat(second.get("id").asLong()).isEqualTo(first.get("id").asLong());
        assertThat(product(p).get("reserved").asInt()).isEqualTo(2);
