        placeOrder(1, "k-diff", null, p, 2).andExpect(status().isCreated());

        placeOrder(1, "k-diff", null, p, 3).andExpect(status().isConflict());
        assertThat(product(p).get("reserved").asInt()).isEqualTo(2);
